{
  "name": "西门子 LOGO! 可编程逻辑控制器",
  "name_en": "Siemens LOGO! programmable logic controller",
  "manufacturer": "Siemens",
  "description": "西门子 LOGO! 是一类紧凑型可编程逻辑控制器/智能继电器，常用于小型自动化控制系统。实验室中可用于读取开关量状态、保存简单变量和模拟量数值，并控制继电器、指示灯、泵阀等基础设备。",
  "description_en": "The Siemens LOGO! is a compact programmable logic controller / smart relay commonly used in small automation systems. In laboratories, it can be used to read digital states, store simple variables and analog values, and control basic equipment such as relays, indicator lamps, pumps, and valves.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到西门子 LOGO! 控制器以进行通信。",
      "description_en": "Connect to the Siemens LOGO! controller for communication."
    },
    {
      "action_name": "auto-read",
      "description": "读取 LOGO! 存储器地址中的状态或数值。",
      "description_en": "Read a status or value from a LOGO! memory address."
    },
    {
      "action_name": "auto-write",
      "description": "向 LOGO! 存储器地址写入状态或数值。",
      "description_en": "Write a status or value to a LOGO! memory address."
    }
  ],
  "tag_hints": [
    "Siemens LOGO!",
    "PLC",
    "smart relay",
    "industrial automation",
    "digital I/O",
    "analog values",
    "VM memory"
  ]
}

